		const sidebar = el(
			"aside",
			{
				id: "sidebar",
				class:
					"fixed inset-y-0 left-0 z-40 w-60 shrink-0 -translate-x-full transform border-r border-white/[0.06] transition-transform duration-300 lg:static lg:translate-x-0",
