				{ class: "flex items-center gap-3" },
				el(
					"button",
					{
						class:
							"relative rounded-lg p-2 text-zinc-400 hover:bg-white/5 hover:text-white transition-colors",
						"aria-label": "通知",
						onclick: () => (location.href = "index.html#recent"),
