					text: (o.username[0] || "A").toUpperCase(),
				}),
			),
		);

		/* ----- 重组 DOM ----- */
		const rightCol = el("div", { class: "flex min-w-0 flex-1 flex-col" });
		const footer = el(
			"footer",
			{
				class:
					"border-t border-white/[0.04] px-5 py-5 text-center text-[11px] text-zinc-600 sm:px-8",
