	/* ---------- API 封装：失败时回退到 demo ---------- */
	async function api(path, opts, demo) {
		const o = opts || {};
		try {
			const res = await fetch(path, Object.assign({ credentials: "include" }, o));
			if (!res.ok) throw new Error("HTTP " + res.status);
			return await res.json();
		} catch (e) {
			if (demo && typeof demo.then === "function") return demo;
			if (demo !== undefined) return demo;
			throw e;
		}
	}

	/* ---------- 小工具 ---------- */
	function copyText(btn, getText) {
		const text = typeof getText === "function" ? getText() : document.querySelector(getText).innerText;
		navigator.clipboard.writeText(text).then(() => {
			const orig = btn.textContent;
			btn.textContent = "已复制 ✓";
			setTimeout(() => (btn.textContent = orig), 1500);
		});
	}

	function toast(msg, kind) {
		let host = document.getElementById("anotify-toast-host");
		if (!host) {
			host = el("div", {
				id: "anotify-toast-host",
				class: "fixed bottom-5 right-5 z-[80] space-y-2",
			});
			document.body.append(host);
		}
		const color =
			kind === "error" ? "var(--error)" : kind === "warn" ? "var(--warn)" : "var(--success)";
		const t = el(
			"div",
			{
				class: "card flex items-center gap-2.5 px-4 py-3 text-sm text-zinc-200 shadow-2xl",
				style: "background: var(--bg-raise)",
			},
			el("span", { class: "dot", style: `background: ${color}` }),
			msg,
		);
		host.append(t);
		setTimeout(() => t.remove(), 3600);
	}

	/* WebAuthn ArrayBuffer <-> base64url */
	function b64urlToBuf(b64) {
		const s = b64.replace(/-/g, "+").replace(/_/g, "/");
		const bin = atob(s + "=".repeat((4 - (s.length % 4)) % 4));
		const buf = new Uint8Array(bin.length);
		for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
		return buf.buffer;
	}
	function bufToB64url(buf) {
		const bytes = new Uint8Array(buf);
		let bin = "";
		for (const b of bytes) bin += String.fromCharCode(b);
		return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
	}

	/* 平台图标（按 platform 字段） */
	const PLATFORM_META = {
		ios: { icon: "📱", label: "iOS Safari" },
		mac: { icon: "💻", label: "macOS" },
		win: { icon: "🖥️", label: "Windows" },
		android: { icon: "🤖", label: "Android" },
		other: { icon: "🌐", label: "浏览器" },
	};

	function detectPlatform() {
		const ua = navigator.userAgent || "";
		if (/iPhone|iPad|iPod/.test(ua)) return "ios";
		if (/Android/.test(ua)) return "android";
		if (/Mac OS X/.test(ua)) return "mac";
		if (/Windows/.test(ua)) return "win";
		return "other";
	}

	function timeAgo(isoOrSec) {
		if (!isoOrSec) return "—";
		let t = typeof isoOrSec === "number" ? isoOrSec * 1000 : Date.parse(isoOrSec);
		if (Number.isNaN(t)) return "—";
		const diff = Date.now() - t;
		if (diff < 60e3) return "刚刚";
		if (diff < 3600e3) return Math.floor(diff / 60e3) + " 分钟前";
		if (diff < 86400e3) return Math.floor(diff / 3600e3) + " 小时前";
		return Math.floor(diff / 86400e3) + " 天前";
	}

	/* ---------- 导出 ---------- */
	window.Anotify = {
		el,
		icon,
		mountLayout,
		closeSidebar,
		api,
		copyText,
		toast,
		b64urlToBuf,
		bufToB64url,
		PLATFORM_META,
		detectPlatform,
		timeAgo,
	};
})();

