/* T22 六页浏览器验证：桌面1280 + 移动390
 * 断言：无 JS 错误、无非 /v1 的 404、侧栏渲染、六页侧栏一致、无横向溢出、可滚动到底
 */
import { chromium } from "playwright-core";

const BASE = "http://localhost:5717";
const PAGES = ["index", "login", "receivers", "keys", "security", "docs"];
const VIEWPORTS = [
	{ name: "desktop", width: 1280, height: 800 },
	{ name: "mobile", width: 390, height: 844 },
];

let browser;
try {
	browser = await chromium.launch({ channel: "chrome", headless: true, args: ["--no-sandbox"] });
} catch {
	browser = await chromium.launch({ headless: true });
}

let totalFail = 0;
const results = [];

for (const vp of VIEWPORTS) {
	for (const p of PAGES) {
		const page = await browser.newPage({ viewport: { width: vp.width, height: vp.height } });
		const jsErrors = [];
		const failedReqs = [];
		const consoleErrors = [];
		page.on("pageerror", (e) => jsErrors.push(String(e)));
		page.on("console", (m) => { if (m.type() === "error") consoleErrors.push(m.text()); });
		page.on("requestfailed", (r) => failedReqs.push(`${r.method()} ${r.url()}`));
		page.on("response", (r) => {
			const u = r.url();
			if (r.status() >= 400 && !u.includes("/v1/")) failedReqs.push(`${r.status()} ${u}`);
		});

		const issues = [];
		try {
			await page.goto(`${BASE}/${p}.html`, { waitUntil: "load", timeout: 20000 });
			await page.waitForTimeout(1400);

			// 侧栏存在 & 链接数
			const sidebarLinks = await page.locator("#sidebar .side-link").count();
			const sidebarVisible = await page.locator("#sidebar").count();
			if (sidebarVisible === 0) issues.push("侧栏 #sidebar 未渲染");
			// login 页无侧栏（公开页）——检查是否有 sidebar
			// 侧栏一致：应为 7 个链接（overview/receivers/keys/agent/api/scheme/security + home=7项）
			if (sidebarVisible > 0 && sidebarLinks < 7) issues.push(`侧栏链接数=${sidebarLinks}（期望≥7）`);

			// 横向溢出
			const overflow = await page.evaluate(() => {
				const vw = window.innerWidth;
				const out = [];
				for (const el of document.querySelectorAll("body *")) {
					const r = el.getBoundingClientRect();
					if (r.right > vw + 2 && !el.closest("pre") && !el.closest(".overflow-x-auto") && !el.closest(".code-body") && !el.closest("nav")) {
						out.push(`${el.tagName}.${(el.className && el.className.baseVal === undefined ? String(el.className) : "").slice(0, 40)} right=${Math.round(r.right)}`);
					}
				}
				return out.slice(0, 6);
			});
			if (overflow.length) issues.push(`横向溢出: ${overflow.join(" | ")}`);

			// 滚动到底
			const canScroll = await page.evaluate(async () => {
				const start = window.scrollY;
				window.scrollTo(0, document.documentElement.scrollHeight);
				await new Promise((r) => setTimeout(r, 300));
				const maxY = document.documentElement.scrollHeight - window.innerHeight;
				const ok = window.scrollY >= maxY - 5 || maxY <= 0;
				window.scrollTo(0, 0);
				return { ok, scrollHeight: document.documentElement.scrollHeight };
			});
			if (!canScroll.ok) issues.push("无法滚动到底");

			if (jsErrors.length) issues.push(`JS错误: ${jsErrors.slice(0, 3).join(" | ")}`);
			if (failedReqs.length) issues.push(`失败请求: ${failedReqs.slice(0, 4).join(" | ")}`);

			// 截图
			const shot = `/tmp/t22-shots/${vp.name}-${p}.png`;
			await page.screenshot({ path: shot, fullPage: true }).catch(() => {});
			results.push({ vp: vp.name, page: p, issues, shot, jsErrors: jsErrors.length, failedReqs: failedReqs.length });
			if (issues.length) totalFail += issues.length;
		} catch (e) {
			results.push({ vp: vp.name, page: p, issues: ["导航失败: " + e], jsErrors: -1, failedReqs: -1 });
			totalFail++;
		}
		await page.close();
	}
}

await browser.close();

console.log("\n===== T22 六页验证结果 =====");
for (const r of results) {
	const mark = r.issues.length === 0 ? "✅" : "❌";
	console.log(`${mark} [${r.vp}] ${r.page}.html  JS错误=${r.jsErrors} 失败请求=${r.failedReqs}`);
	for (const i of r.issues) console.log(`     ⚠️ ${i}`);
	if (r.shot) console.log(`     📸 ${r.shot}`);
}
console.log(`\n总计问题: ${totalFail}`);
process.exit(totalFail === 0 ? 0 : 1);

