arguments.command:
cd /Users/zheng/code/anotify && cat > /tmp/t22-nav-check.mjs <<'EOF'
import { chromium } from "playwright-core";
const BASE = "http://localhost:5717";
const PAGES = ["index", "receivers", "keys", "security", "docs"]; // login 为公开页无侧栏
let browser;
try { browser = await chromium.launch({ channel: "chrome", headless: true, args: ["--no-sandbox"] }); }
catch { browser = await chromium.launch({ headless: true }); }
const navs = {};
for (const p of PAGES) {
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  await page.goto(`${BASE}/${p}.html`, { waitUntil: "load" });
  await page.waitForTimeout(1000);
  navs[p] = await page.evaluate(() =>
    Array.from(document.querySelectorAll("#sidebar .side-link")).map((a) => ({
      text: a.textContent.trim(),
      href: a.getAttribute("href"),
      active: a.classList.contains("active"),
    }))
  );
  await page.close();
}
await browser.close();
// 一致性：所有页的非 active 链接序列应完全一致（文本+href）
const sig = (arr) => JSON.stringify(arr.map(({ text, href }) => [text, href]));
const base = sig(navs[PAGES[0]]);
let consistent = true;
for (const p of PAGES) {
  const same = sig(navs[p]) === base;
  const activeCount = navs[p].filter((x) => x.active).length;
  console.log(`${same ? "✅" : "❌"} ${p}.html 侧栏一致=${same} 链接数=${navs[p].length} 高亮=${activeCount} (${navs[p].find(x=>x.active)?.text || "无"})`);
  if (!same || activeCount !== 1) consistent = false;
}
console.log(consistent ? "\n✅ 六页（含login公开页）侧栏完全一致，每页恰好1个高亮" : "\n❌ 侧栏不一致");
process.exit(consistent ? 0 : 1);
EOF
cp /tmp/t22-nav-check.mjs ./t22-nav-check.mjs && node t22-nav-check.mjs 2>&1 | tail -12

